import numpy as np

def kernel(x, t, D=1):
    return np.exp(-x ** 2 / (4 * D * t)) / np.sqrt(4 * np.pi * D * t)

def heat_line(u0, x, t, D=1, n=4001):
    """u(x, t): trapezium rule on n points."""
    w = np.sqrt(2 * D * t)
    y = np.linspace(x - 10 * w, x + 10 * w, n)
    f = kernel(x - y, t, D) * u0(y)
    h = y[1] - y[0]
    return float(h * (f.sum() - 0.5 * f[0] - 0.5 * f[-1]))
